const reportPct=v=>v==null?"—":(v*100).toLocaleString("es-ES",{minimumFractionDigits:2,maximumFractionDigits:2})+"%";
async function rows(fields){let all=[],from=0;while(true){const q=await sb.from("estadisticas_registros").select(["fecha_protocolo",...fields].join(",")).not("fecha_protocolo","is",null).order("fecha_protocolo",{ascending:true}).range(from,from+999);if(q.error)throw q.error;all=all.concat(q.data||[]);if(!q.data||q.data.length<1000)break;from+=1000}return all}
async function years(){const r=await rows([]);const y=[...new Set(r.map(x=>Number(String(x.fecha_protocolo||"").slice(0,4))).filter(x=>x>1900))].sort((a,b)=>a-b);return y.length?y:[new Date().getFullYear()]}async function latestMonth(){const q=await sb.from("estadisticas_registros").select("fecha_protocolo").not("fecha_protocolo","is",null).order("fecha_protocolo",{ascending:false}).limit(1);if(q.error)throw q.error;return Number(String(q.data?.[0]?.fecha_protocolo||"").slice(5,7))||12}
function model(data,field,c){const ys=Array.from({length:Math.min(30,Math.max(0,c.yearTo-c.yearFrom+1))},(_,i)=>c.yearFrom+i),ms=Array.from({length:Math.max(0,c.monthTo-c.monthFrom+1)},(_,i)=>c.monthFrom+i),rs=data.filter(r=>{const d=String(r.fecha_protocolo||"");return ys.includes(+d.slice(0,4))&&ms.includes(+d.slice(5,7))}),labels=[...new Set(rs.map(r=>String(r[field]??"").trim()||"Sin clasificar"))],counts={},totals={};labels.forEach(l=>{counts[l]={};ys.forEach(y=>{counts[l][y]={};ms.forEach(m=>counts[l][y][m]=0)})});ys.forEach(y=>{totals[y]={};ms.forEach(m=>totals[y][m]=0)});rs.forEach(r=>{const d=String(r.fecha_protocolo||""),y=+d.slice(0,4),m=+d.slice(5,7),l=String(r[field]??"").trim()||"Sin clasificar";if(counts[l]){counts[l][y][m]++;totals[y][m]++}});const sum=(o,y)=>ms.reduce((a,m)=>a+(o[y]?.[m]||0),0),out=labels.map(label=>({label,values:ys.map(year=>({year,counts:ms.map(m=>counts[label][year][m]||0),total:sum(counts[label],year),percentages:ms.map(m=>totals[year][m]?counts[label][year][m]/totals[year][m]:null),totalPercentage:sum(totals,year)?sum(counts[label],year)/sum(totals,year):null}))})).sort((a,b)=>b.values.reduce((x,v)=>x+v.total,0)-a.values.reduce((x,v)=>x+v.total,0)||a.label.localeCompare(b.label,"es"));const total={label:"Total",values:ys.map(year=>({year,counts:ms.map(m=>totals[year][m]||0),total:sum(totals,year),percentages:ms.map(m=>totals[year][m]?1:null),totalPercentage:sum(totals,year)?1:null}))};return {field,years:ys,months:ms,rows:out,totalRow:total,count:rs.length,blank:rs.filter(r=>!String(r[field]??"").trim()).length}}
function table(m,c){const pct=c.showPercent!==false,tot=c.showTotal!==false,mc=m.months.length+(tot?1:0),bc=mc*(pct?2:1),top=m.years.map(y=>'<th class="year-group" colspan="'+bc+'">'+y+'</th>').join(""),groups=m.years.map(()=>'<th class="metric-group" colspan="'+mc+'">Firmas</th>'+(pct?'<th class="metric-group percent-group" colspan="'+mc+'">%</th>':"")).join(""),ml=m.months.map(x=>M[x-1]).join("</th><th>"),labels=m.years.map(()=>'<th>'+ml+'</th>'+(tot?'<th class="total-col">Total</th>':"")+(pct?'<th>'+ml+'</th>'+(tot?'<th class="total-col">Total</th>':""):"")).join(""),cells=r=>r.values.map(v=>v.counts.map(x=>'<td class="numeric">'+n(x)+'</td>').join("")+(tot?'<td class="numeric total-col">'+n(v.total)+'</td>':"")+(pct?v.percentages.map(x=>'<td class="numeric percent-cell">'+p(x)+'</td>').join("")+(tot?'<td class="numeric percent-cell total-col">'+p(v.totalPercentage)+'</td>':""):"")).join(""),name=F.find(x=>x[0]===m.field)?.[1]||m.field,sz=Math.min(16,Math.max(8,+c.fontSize||10));return '<section class="report-section" style="--report-primary:'+color(c.primaryColor,"#064675")+';--report-header:'+color(c.headerColor,"#EAF2F8")+';--report-text:'+color(c.textColor,"#17354A")+';--report-font-size:'+sz+'px;--report-font-family:'+esc(c.fontFamily||"Inter")+'"><div class="report-print-head">'+(c.showLogo!==false?'<img src="'+esc(logo(c.logoUrl))+'" alt="Molsan" class="report-logo">':"")+'<div class="report-page-heading">'+(c.pageHeader?'<div class="report-overline">'+esc(c.pageHeader)+'</div>':"")+'<h1>'+esc(c.title||"Informe estadístico MOLSAN")+'</h1>'+(c.subtitle?'<p>'+esc(c.subtitle)+'</p>':"")+'</div></div><div class="report-meta"><span>'+esc(name)+'</span><span>'+m.years[0]+'–'+m.years[m.years.length-1]+'</span></div><div class="report-table-wrap"><table class="report-matrix"><thead><tr><th rowspan="3" class="report-concept-head">'+esc(name)+'</th>'+top+'</tr><tr>'+groups+'</tr><tr>'+labels+'</tr></thead><tbody>'+m.rows.map(r=>'<tr><th scope="row">'+esc(r.label)+'</th>'+cells(r)+'</tr>').join("")+(tot?'<tr class="report-total-row"><th>Total</th>'+cells(m.totalRow)+'</tr>':"")+'</tbody></table></div><div class="report-print-footer"><span>'+esc(c.pageFooter||"MOLSAN · Control estadístico")+'</span><span class="report-page-number">Página </span></div><div class="report-data-note">'+n(m.count)+' firmas contabilizadas · '+n(m.blank)+' sin clasificar</div></section>'}
function excel(models,c){const wb=XLSX.utils.book_new(),pct=c.showPercent!==false,tot=c.showTotal!==false;models.forEach(m=>{const mc=m.months.length+(tot?1:0),bc=mc*(pct?2:1),a=[[F.find(x=>x[0]===m.field)?.[1]||"Concepto",...m.years.flatMap(y=>Array(bc).fill(y))],["",...m.years.flatMap(()=>[...Array(mc).fill("Firmas"),...(pct?Array(mc).fill("%"):[])])],["",...m.years.flatMap(()=>[...m.months.map(x=>M[x-1]),...(tot?["Total"]:[]),...(pct?[...m.months.map(x=>M[x-1]),...(tot?["Total"]:[])]:[])])]];[...m.rows,...(tot?[m.totalRow]:[])].forEach(r=>{const line=[r.label];r.values.forEach(v=>{line.push(...v.counts);if(tot)line.push(v.total);if(pct){line.push(...v.percentages);if(tot)line.push(v.totalPercentage)}});a.push(line)});const ws=XLSX.utils.aoa_to_sheet(a),merges=[{s:{r:0,c:0},e:{r:2,c:0}}];let col=1;m.years.forEach(()=>{merges.push({s:{r:0,c:col},e:{r:0,c:col+bc-1}},{s:{r:1,c:col},e:{r:1,c:col+mc-1}});if(pct){merges.push({s:{r:1,c:col+mc},e:{r:1,c:col+bc-1}});for(let j=0;j<mc;j++)for(let r=3;r<a.length;r++){const x=ws[XLSX.utils.encode_cell({r,c:col+mc+j})];if(x&&typeof x.v==="number")x.z="0.00%"}}col+=bc});ws["!merges"]=merges;ws["!freeze"]={xSplit:1,ySplit:3,topLeftCell:"B4",activePane:"bottomRight",state:"frozen"};ws["!cols"]=[{wch:28},...Array(m.years.length*bc).fill({wch:12})];XLSX.utils.book_append_sheet(wb,ws,(F.find(x=>x[0]===m.field)?.[1]||m.field).slice(0,31))});XLSX.writeFile(wb,"MOLSAN_informes_estadisticos.xlsx")}

async function appendEvolutionReport(target,c){
 const field=c.evolutionField||"centro_encargo",mode=c.evolutionMode||"global",category=c.evolutionCategory||"";
 const data=await rows([field]),years=Array.from({length:Math.min(30,c.yearTo-c.yearFrom+1)},(_,i)=>c.yearFrom+i);
 const latest=years[years.length-1],lastMonth=Math.max(1,...data.filter(r=>+String(r.fecha_protocolo||"").slice(0,4)===latest).map(r=>+String(r.fecha_protocolo||"").slice(5,7)||0));
 const months=Array.from({length:12},(_,i)=>i+1),counts={};years.forEach(y=>counts[y]=Array(12).fill(0));
 data.forEach(r=>{const d=String(r.fecha_protocolo||""),y=+d.slice(0,4),m=+d.slice(5,7),v=String(r[field]??"").trim()||"Sin clasificar";if(!counts[y]||m<1||m>12)return;if(mode==="dimension"&&category&&v!==category)return;counts[y][m-1]++});
 const totals=years.map(y=>months.slice(0,lastMonth).reduce((a,m)=>a+counts[y][m-1],0));
 const delta=i=>i&&totals[i-1]?(totals[i]/totals[i-1]-1):null;
 const annualTotals=years.map(y=>counts[y].reduce((a,v)=>a+v,0));
 const monthlyTotal=i=>years.reduce((a,y)=>a+((y===latest&&i+1>lastMonth)?0:counts[y][i]),0);
 const cumulative=years.map(y=>counts[y].slice(0,lastMonth).reduce((a,v)=>a+v,0));
 const table='<div class="report-table-wrap"><table class="report-matrix evolution-matrix"><thead><tr><th rowspan="2" class="report-concept-head">Mes</th><th class="year-group" colspan="'+years.length+'">Firmas por año</th><th rowspan="2" class="total-col">Total</th>'+(years.length>1?'<th class="year-group" colspan="'+(years.length-1)+'">Variación interanual</th>':"")+'</tr><tr>'+years.map(y=>'<th class="metric-group">'+y+'</th>').join("")+years.slice(1).map(y=>'<th class="metric-group">'+y+'</th>').join("")+'</tr></thead><tbody>'
 +M.map((m,i)=>'<tr><th scope="row">'+m+'</th>'+years.map(y=>'<td class="numeric">'+(y===latest&&i+1>lastMonth?'':n(counts[y][i]))+'</td>').join("")+'<td class="numeric total-col">'+n(monthlyTotal(i))+'</td>'+years.slice(1).map((y,j)=>{const prev=counts[years[j]][i],cur=counts[y][i];if(y===latest&&i+1>lastMonth)return '<td class="numeric evolution-empty"></td>';return '<td class="numeric">'+(prev?reportPct(cur/prev-1):'')+'</td>'}).join("")+'</tr>').join("")
 +'<tr class="report-total-row"><th>Total general</th>'+annualTotals.map(v=>'<td class="numeric">'+n(v)+'</td>').join("")+'<td class="numeric total-col">'+n(annualTotals.reduce((a,v)=>a+v,0))+'</td>'+years.slice(1).map((y,j)=>annualTotals[j]?'<td class="numeric">'+reportPct(annualTotals[j+1]/annualTotals[j]-1)+'</td>':'<td class="numeric evolution-empty"></td>').join("")+'</tr>'
 +'<tr class="evolution-spacer-row"><th colspan="'+(years.length*2+1)+'"></th></tr>'
 +'<tr class="evolution-comparable-row"><th>Hasta '+M[lastMonth-1]+'</th>'+cumulative.map(v=>'<td class="numeric">'+n(v)+'</td>').join("")+'<td class="numeric total-col"></td>'+years.slice(1).map(()=>'<td class="numeric"></td>').join("")+'</tr>'
 +'<tr class="evolution-volume-row"><th>Evolución % volumen firmas</th>'+cumulative.map((v,j)=>'<td class="numeric">'+(j&&cumulative[j-1]?reportPct(v/cumulative[j-1]-1):'')+'</td>').join("")+'<td class="numeric total-col"></td>'+years.slice(1).map(()=>'<td class="numeric"></td>').join("")+'</tr></tbody></table></div>'
 const title=mode==="dimension"?(F.find(x=>x[0]===field)?.[1]||field)+(category?" · "+category:" · todas las categorías"):"Evolución global de firmas";
 const primary=color(c.primaryColor,"#064675"),headerColor=color(c.headerColor,"#EAF2F8"),textColor=color(c.textColor,"#17354A"),fontSize=Math.min(16,Math.max(8,+c.fontSize||10));
 const reportContainer=target.querySelector(".report-document")||target;reportContainer.insertAdjacentHTML("beforeend",'<section class="report-section evolution-report-section" style="--report-primary:'+primary+';--report-header:'+headerColor+';--report-text:'+textColor+';--report-font-size:'+fontSize+'px;--report-font-family:'+esc(c.fontFamily||"Inter")+'"><div class="report-print-head">'+(c.showLogo!==false?'<img src="'+esc(logo(c.logoUrl))+'" alt="Molsan" class="report-logo">':"")+'<div class="report-page-heading">'+(c.pageHeader?'<div class="report-overline">'+esc(c.pageHeader)+'</div>':"")+'<h1>'+esc(c.title||"Informe estadístico MOLSAN")+'</h1><p>'+esc(c.subtitle||"Evolución mensual e interanual del volumen de firmas.")+'</p></div></div><div class="report-meta"><span>'+esc(title)+'</span><span>'+years[0]+'–'+latest+'</span></div><h2 class="evolution-report-title">Evolución mensual e interanual</h2><div class="evolution-report-kpis"><div><small>Firmas acumuladas · '+latest+'</small><strong>'+n(totals[totals.length-1])+'</strong></div><div><small>Variación acumulada</small><strong>'+reportPct(delta(years.length-1))+'</strong></div><div><small>Media mensual</small><strong>'+n(Math.round(totals[totals.length-1]/lastMonth))+'</strong></div></div>'+table+'<div class="report-data-note">Comparación hasta '+M[lastMonth-1]+' para todos los años. Meses futuros del último ejercicio sin datos se muestran vacíos.</div><div class="report-print-footer"><span>'+esc(c.pageFooter||"MOLSAN · Control estadístico")+'</span><span class="report-page-number">Página </span></div></section>');
}

async function generate(c,target){if(!c.campos?.length)throw Error("Selecciona al menos un campo.");if(c.yearTo<c.yearFrom||c.monthTo<c.monthFrom)throw Error("Revisa el intervalo de años y meses.");const data=await rows(c.campos),ms=c.campos.map(f=>model(data,f,c));let printStyle=document.getElementById("report-print-settings");if(!printStyle){printStyle=document.createElement("style");printStyle.id="report-print-settings";document.head.appendChild(printStyle)}const paper=["A4","A3","Letter"].includes(c.paper)?c.paper:"A4",orientation=c.orientation==="portrait"?"portrait":"landscape";printStyle.textContent="@page{size:"+paper+" "+orientation+";margin:12mm}";target.innerHTML='<div class="report-document">'+ms.map(m=>table(m,c)).join("")+'</div>';const count=ms.reduce((a,m)=>a+m.count,0),blank=ms.reduce((a,m)=>a+m.blank,0);if(!count)target.insertAdjacentHTML("afterbegin",'<div class="notice">No hay expedientes con fecha de protocolo en el periodo seleccionado.</div>');else if(count===blank)target.insertAdjacentHTML("afterbegin",'<div class="notice">Los campos seleccionados todavía no tienen valores calculados para este periodo. Se muestran como «Sin clasificar». El informe no modifica ni recalcula expedientes.</div>');target.insertAdjacentHTML("afterbegin",'<div class="report-output-actions no-print"><button class="btn secondary small" id="report-print">Imprimir / Guardar PDF</button><button class="btn primary small" id="report-xlsx">Exportar Excel</button></div>');target.querySelector("#report-print").onclick=()=>window.print();target.querySelector("#report-xlsx").onclick=()=>excel(ms,c)}
const yopts=(ys,s)=>ys.map(y=>'<option value="'+y+'" '+(+s===y?"selected":"")+'>'+y+'</option>').join(""),mopts=s=>M.map((m,i)=>'<option value="'+(i+1)+'" '+(i+1===+s?"selected":"")+'>'+m+'</option>').join("");
async function informes(h){const [ys,lm,ts]=await Promise.all([years(),latestMonth(),sb.from("estadisticas_plantillas_informes").select("id,nombre,configuracion").eq("activa",true).order("nombre")]);if(ts.error)throw ts.error;ts.data=(ts.data||[]).filter(t=>t.configuracion?.tipoDocumento!=="acta");h.innerHTML=head("Informes","Informes mensuales y anuales por los siete campos calculados.",'<button class="btn secondary small" data-view="plantillas-informes">⚙ Diseñador de informes</button>')+'<section class="card report-filter-card"><div class="card-title"><div><h3>Configurar informe</h3><p>Los años aparecen en la cabecera; cada ejercicio contiene Firmas y %.</p></div><span class="pill">7 campos disponibles</span></div><div class="report-filter-grid"><div class="field full-span"><label>Campos del informe · marca los que quieras incluir y ordénalos con ↑ y ↓</label><div id="report-fields" class="report-fields-picker">'+checks(["centro_encargo"])+'</div></div><label>Año inicial<select id="report-year-from">'+yopts(ys,ys[0])+'</select></label><label>Año final<select id="report-year-to">'+yopts(ys,ys[ys.length-1])+'</select></label><label>Mes inicial<select id="report-month-from">'+mopts(1)+'</select></label><label>Mes final<select id="report-month-to">'+mopts(lm)+'</select></label></div><div class="report-filter-options"><label><input id="report-show-percent" type="checkbox" checked> Mostrar porcentajes</label><label><input id="report-show-total" type="checkbox" checked> Mostrar totales</label><label><input id="report-include-evolution" type="checkbox"> Incluir informe evolutivo (tabla)</label><label>Tipo de evolución<select id="report-evolution-mode" disabled><option value="global">Global</option><option value="dimension">Por dimensión</option></select></label><label>Dimensión<select id="report-evolution-field" disabled><option value="centro_encargo">Centro de encargo</option><option value="tipo_gestion">Tipo Gestión</option><option value="nombre_apoderado">Apoderados</option><option value="centro_firma">Centro que firma</option><option value="entidad">Entidad</option><option value="circuito_notarial">Circuito notarial</option><option value="tipo_firma">Tipo de firma</option></select></label><label>Categoría<select id="report-evolution-category" disabled><option value="">Todas las categorías</option></select></label><label>Plantilla<select id="report-template"><option value="">Sin plantilla</option>'+(ts.data||[]).map(t=>'<option value="'+t.id+'">'+esc(t.nombre)+'</option>').join("")+'</select></label></div><div class="report-filter-actions"><button id="report-generate" class="btn primary">Generar informe</button></div></section><div id="report-output"></div>';const fs=$("#report-fields");let loadedTemplate=null;enableFieldDragging(fs);const evToggle=$("#report-include-evolution"),evMode=$("#report-evolution-mode"),evField=$("#report-evolution-field"),evCategory=$("#report-evolution-category");evToggle.onchange=()=>{evMode.disabled=!evToggle.checked;evField.disabled=!evToggle.checked||evMode.value!=="dimension";evCategory.disabled=!evToggle.checked||evMode.value!=="dimension";};const loadEvolutionCategories=async()=>{try{const rr=await rows([evField.value]),vals=[...new Set(rr.map(x=>String(x[evField.value]??"").trim()||"Sin clasificar"))].sort((a,b)=>a.localeCompare(b,"es"));evCategory.innerHTML='<option value="">Todas las categorías</option>'+vals.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join("");}catch(e){msg("No se pudieron cargar las categorías: "+e.message)}};evMode.onchange=()=>{evField.disabled=!evToggle.checked||evMode.value!=="dimension";evCategory.disabled=!evToggle.checked||evMode.value!=="dimension";if(evToggle.checked&&evMode.value==="dimension")loadEvolutionCategories()};evField.onchange=loadEvolutionCategories;$("#report-template").onchange=()=>{const t=(ts.data||[]).find(x=>x.id===$("#report-template").value);if(!t){loadedTemplate=null;return}const c=t.configuracion||{};loadedTemplate=c;fs.querySelectorAll('[name="report-fields"]').forEach(o=>o.checked=(c.campos||[]).includes(o.value));reorderFieldRows(fs,c.campos||[]);$("#report-year-from").value=String(c.yearFrom||ys[0]);$("#report-year-to").value=String(c.yearTo||ys[ys.length-1]);$("#report-month-from").value=String(c.monthFrom||1);$("#report-month-to").value=String(c.monthTo||lm);$("#report-show-percent").checked=c.showPercent!==false;$("#report-show-total").checked=c.showTotal!==false};$("#report-generate").onclick=async()=>{const b=$("#report-generate");b.disabled=true;b.textContent="Generando…";try{const cfg={...(loadedTemplate||{}),campos:[...fs.querySelectorAll('[name="report-fields"]:checked')].map(o=>o.value),title:loadedTemplate?.title||"Informe estadístico MOLSAN",subtitle:loadedTemplate?.subtitle||"Distribución mensual de firmas y peso porcentual por concepto.",pageHeader:loadedTemplate?.pageHeader||"ESTADÍSTICAS-MOLSAN",pageFooter:loadedTemplate?.pageFooter||"MOLSAN · Control estadístico",logoUrl:loadedTemplate?.logoUrl||"img/molsan-logo.svg",showLogo:loadedTemplate?.showLogo!==false,yearFrom:+$("#report-year-from").value,yearTo:+$("#report-year-to").value,monthFrom:+$("#report-month-from").value,monthTo:+$("#report-month-to").value,showPercent:$("#report-show-percent").checked,showTotal:$("#report-show-total").checked,fontSize:loadedTemplate?.fontSize||10,orientation:loadedTemplate?.orientation||"landscape",paper:loadedTemplate?.paper||"A4",fontFamily:loadedTemplate?.fontFamily||"Inter",primaryColor:loadedTemplate?.primaryColor||"#064675",headerColor:loadedTemplate?.headerColor||"#EAF2F8",textColor:loadedTemplate?.textColor||"#17354A"};await generate(cfg,$("#report-output"));if($("#report-include-evolution").checked)await appendEvolutionReport($("#report-output"),{...cfg,evolutionMode:$("#report-evolution-mode").value,evolutionField:$("#report-evolution-field").value,evolutionCategory:$("#report-evolution-category").value})}catch(e){$("#report-output").innerHTML='<div class="notice">'+esc(e.message)+'</div>'}finally{b.disabled=false;b.textContent="Generar informe"}}}
