const EV_FIELDS=[["centro_encargo","Centro de encargo"],["tipo_gestion","Tipo Gestión"],["nombre_apoderado","Apoderados"],["centro_firma","Centro que firma"],["entidad","Entidad"],["circuito_notarial","Circuito notarial"],["tipo_firma","Tipo de firma"]];
