  const latestYear=years[years.length-1],latestMonthValue=Math.max(1,...data.filter(r=>+String(r.fecha_protocolo||"").slice(0,4)===latestYear).map(r=>+String(r.fecha_protocolo||"").slice(5,7)||0));
