    $ev("ev-chart-title").textContent=mode==="dimension"?"Evolución de "+(EV_FIELDS.find(x=>x[0]===field)?.[1]||field)+(category?" · "+category:" · todas las categorías"):"Evolución mensual de firmas";
    $ev("ev-chart-badge").textContent=ys.length+" ejercicios";
    const W=900,H=300,L=56,R=20,T=18,B=42,plotW=W-L-R,plotH=H-T-B,max=Math.max(1,...ys.flatMap(y=>counts[y].slice(0,y===latestYear?latestMonthValue:12)));
